select
    SB2.B2_FILIAL,
    SB2.B2_COD,
    SB1.B1_DESC,
    SB2.B2_LOCAL,
    SB2.B2_QFIM,
    SB2.B2_QATU,
    SB2.B2_CM1,

    (select )

from SB2010 SB2 (nolock)
    inner join SB1010 SB1 (nolock)
        on SB1.D_E_L_E_T_ = ''
        and SB1.B1_COD = SB2.B2_COD
where
        SB2.D_E_L_E_T_ = ''
    and SB2.B2_COD in ('14010001', '14010020', '14010070', '14010071', '14010080', '14010098', '14010099', '14010101', '14010136', '14010170', '14010171', '14010172', '14010187', '14010189', '14010192', '14010193', '14010194', '14010195', '14010203', '14010206', '14010207', '14010208', '14010209', '14010211', '14010212', '14010215', '14010216', '14010217', '14010229', '14010230', '14010231', '14010232', '14010233', '14010235', '14010248', '14010249', '14010258', '14010269', '14010400', '14010401', '14010403', '14010404', '14010405', '14010406', '14010416', '14010426', '14010427', '14010433', '14010434', '14010435', '14010453', '14010466', '14010467', '14010468', '14010484', '14010487')
